<!-- HERO -->\n<section class=\"ep-hero\">\n  <!-- LEFT -->\n  <div class=\"ep-left\">\n    <p class=\"ep-tag\">Eau de Parfum · 50ml</p>\n    <h1 class=\"ep-h1\">\n      Hương thơm<br>\n      của <em>sự tự tin</em><br>\n      &amp; cuốn hút\n    </h1>\n    <p class=\"ep-desc\">\n      Được tạo ra cho người phụ nữ hiện đại — tinh tế, thanh lịch và đầy lôi cuốn. Công thức EDP nồng độ cao lưu hương bền bỉ suốt cả ngày dài.\n    </p>\n    <div class=\"ep-price-row\">\n      <span class=\"ep-price\">599.000₫</span>\n      <span class=\"ep-oldprice\">799.000₫</span>\n      <span class=\"ep-badge-ship\">Miễn ship</span>\n    </div>\n    <div class=\"ep-actions\">\n      <a href=\"#epOrder\" class=\"ep-btn-dark\">Mua ngay →</a>\n      <a href=\"#epNotes\" class=\"ep-btn-ghost\">Khám phá</a>\n    </div>\n  </div>\n\n  <!-- RIGHT: SLIDER -->\n  <div class=\"ep-right\">\n    <div class=\"ep-slide on\">\n      <img decoding=\"async\" src=\"https://marketing2student.com/wp-content/uploads/IMG_4054.jpeg\" alt=\"ELORA EDP\" loading=\"eager\">\n    </div>\n    <div class=\"ep-slide\">\n      <img decoding=\"async\" src=\"https://marketing2student.com/wp-content/uploads/IMG_4052.jpeg\" alt=\"ELORA EDP\" loading=\"lazy\">\n    </div>\n    <div class=\"ep-slide\">\n      <img decoding=\"async\" src=\"https://marketing2student.com/wp-content/uploads/IMG_4053.jpeg\" alt=\"ELORA EDP\" loading=\"lazy\">\n    </div>\n    <div class=\"ep-slide\">\n      <img decoding=\"async\" src=\"https://marketing2student.com/wp-content/uploads/IMG_4055.jpeg\" alt=\"ELORA EDP\" loading=\"lazy\">\n    </div>\n    <button class=\"ep-arrow ep-arrow-l\" onclick=\"epSlide(-1)\" aria-label=\"Trước\">‹</button>\n    <button class=\"ep-arrow ep-arrow-r\" onclick=\"epSlide(1)\"  aria-label=\"Sau\">›</button>\n    <div class=\"ep-slide-pill\">\n      <div class=\"ep-pill-dot\"></div>\n      <div class=\"ep-pill-txt\"><strong>2.400+</strong> khách tin dùng</div>\n    </div>\n    <div class=\"ep-dots\" id=\"epDots\">\n      <button class=\"ep-dot on\" onclick=\"epGoTo(0)\"></button>\n      <button class=\"ep-dot\"    onclick=\"epGoTo(1)\"></button>\n      <button class=\"ep-dot\"    onclick=\"epGoTo(2)\"></button>\n      <button class=\"ep-dot\"    onclick=\"epGoTo(3)\"></button>\n    </div>\n  </div>\n</section>\n\n<!-- STRIP -->\n<div class=\"ep-strip\">\n  <div class=\"ep-strip-track\" aria-hidden=\"true\">\n    <div class=\"ep-strip-item\"><span>✦</span> Lưu hương 8–12 giờ</div>\n    <div class=\"ep-strip-item\"><span>✦</span> Thành phần tự nhiên</div>\n    <div class=\"ep-strip-item\"><span>✦</span> Miễn phí vận chuyển toàn quốc</div>\n    <div class=\"ep-strip-item\"><span>✦</span> Đổi trả trong 7 ngày</div>\n    <div class=\"ep-strip-item\"><span>✦</span> An toàn cho da nhạy cảm</div>\n    <div class=\"ep-strip-item\"><span>✦</span> Nồng độ EDP cao cấp</div>\n    <div class=\"ep-strip-item\"><span>✦</span> Lưu hương 8–12 giờ</div>\n    <div class=\"ep-strip-item\"><span>✦</span> Thành phần tự nhiên</div>\n    <div class=\"ep-strip-item\"><span>✦</span> Miễn phí vận chuyển toàn quốc</div>\n    <div class=\"ep-strip-item\"><span>✦</span> Đổi trả trong 7 ngày</div>\n    <div class=\"ep-strip-item\"><span>✦</span> An toàn cho da nhạy cảm</div>\n    <div class=\"ep-strip-item\"><span>✦</span> Nồng độ EDP cao cấp</div>\n  </div>\n</div>\n\n<!-- FEATURES -->\n<section class=\"ep-features\">\n  <div class=\"ep-feat-grid\">\n    <div class=\"ep-feat r\">\n      <div class=\"ep-feat-ico\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M12 2C8.5 5.5 5 8.5 5 13a7 7 0 0014 0c0-4.5-3.5-7.5-7-11z\"/></svg>\n      </div>\n      <h3 class=\"ep-feat-name\">Tinh Tế &amp; Nữ Tính</h3>\n      <p class=\"ep-feat-desc\">Mùi hương thanh lịch, phù hợp mọi dịp — từ văn phòng buổi sáng đến buổi hẹn hò tối muộn. Không quá ngọt, không quá nồng.</p>\n    </div>\n    <div class=\"ep-feat r\">\n      <div class=\"ep-feat-ico\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/><path d=\"M9 12l2 2 4-4\"/></svg>\n      </div>\n      <h3 class=\"ep-feat-name\">Thành Phần Tự Nhiên</h3>\n      <p class=\"ep-feat-desc\">Chiết xuất chọn lọc từ thiên nhiên, an toàn cho da nhạy cảm. Không cồn nặng, không gây kích ứng, không thử nghiệm trên động vật.</p>\n    </div>\n    <div class=\"ep-feat r\">\n      <div class=\"ep-feat-ico\">\n        <svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M12 1v3M12 20v3M4.22 4.22l2.12 2.12M17.66 17.66l2.12 2.12M1 12h3M20 12h3M4.22 19.78l2.12-2.12M17.66 6.34l2.12-2.12\"/></svg>\n      </div>\n      <h3 class=\"ep-feat-name\">Lưu Hương Cả Ngày</h3>\n      <p class=\"ep-feat-desc\">Công thức EDP nồng độ cao (15–20%) giúp mùi hương tỏa bền bỉ 8–12 giờ liên tục mà không cần xịt lại.</p>\n    </div>\n  </div>\n</section>\n\n<!-- GALLERY -->\n<div class=\"ep-gallery\">\n  <img decoding=\"async\" src=\"https://marketing2student.com/wp-content/uploads/IMG_4052.jpeg\" alt=\"ELORA\" loading=\"lazy\">\n  <img decoding=\"async\" src=\"https://marketing2student.com/wp-content/uploads/IMG_4053.jpeg\" alt=\"ELORA\" loading=\"lazy\">\n  <img decoding=\"async\" src=\"https://marketing2student.com/wp-content/uploads/IMG_4055.jpeg\" alt=\"ELORA\" loading=\"lazy\">\n  <img decoding=\"async\" src=\"https://marketing2student.com/wp-content/uploads/IMG_4056.jpeg\" alt=\"ELORA\" loading=\"lazy\">\n</div>\n\n<!-- NOTES DARK -->\n<section class=\"ep-notes\" id=\"epNotes\">\n  <div class=\"ep-notes-inner\">\n    <div class=\"r\">\n      <div class=\"ep-eyebrow\">Câu chuyện mùi hương</div>\n      <h2 class=\"ep-notes-title\">Được tạo ra cho người phụ nữ biết mình muốn gì</h2>\n      <p class=\"ep-notes-body\">ELORA ra đời từ cảm hứng của sự thanh lịch không cần cố gắng. Một mùi hương cân bằng tinh tế giữa hoa tươi và gỗ ấm — để lại dấu ấn khó quên mà không cần to tiếng.</p>\n      <a href=\"#epOrder\" class=\"ep-btn-gold\">Sở hữu ngay →</a>\n    </div>\n    <div class=\"ep-note-stack r\">\n      <div class=\"ep-note-row\">\n        <div><div class=\"ep-note-type\">Top Note</div><div class=\"ep-note-name\">Bergamot</div></div>\n        <div class=\"ep-note-vbar\"></div>\n        <div class=\"ep-note-info\">Khai mở tươi sáng với citrus nhẹ nhàng, tạo cảm giác sảng khoái và thu hút ngay lập tức.</div>\n      </div>\n      <div class=\"ep-note-row\">\n        <div><div class=\"ep-note-type\">Heart Note</div><div class=\"ep-note-name\">Hoa Mẫu Đơn</div></div>\n        <div class=\"ep-note-vbar\"></div>\n        <div class=\"ep-note-info\">Trái tim ngọt ngào, nữ tính với mẫu đơn và hồng tươi — tầng hương đặc trưng của ELORA.</div>\n      </div>\n      <div class=\"ep-note-row\">\n        <div><div class=\"ep-note-type\">Base Note</div><div class=\"ep-note-name\">Sandalwood</div></div>\n        <div class=\"ep-note-vbar\"></div>\n        <div class=\"ep-note-info\">Nền gỗ đàn hương ấm áp, quyến rũ — tạo chiều sâu và giúp lưu hương lâu nhất trên da.</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- REVIEWS -->\n<section class=\"ep-reviews\">\n  <div class=\"ep-reviews-head r\">\n    <h2 class=\"ep-reviews-title\">Hơn 2.400 người<br>đã yêu thích ELORA</h2>\n    <div class=\"ep-rating\">\n      <div class=\"ep-stars\">★★★★★</div>\n      <div class=\"ep-rating-cnt\">4.9 / 5 · 847 đánh giá</div>\n    </div>\n  </div>\n  <div class=\"ep-rev-grid\">\n    <div class=\"ep-rev r\">\n      <div class=\"ep-rev-stars\">★★★★★</div>\n      <p class=\"ep-rev-text\">\"Mình thử rất nhiều nước hoa nhưng ELORA là lần đầu dùng hết cả chai. Mùi thực sự dễ chịu và lưu lâu đến bất ngờ — đồng nghiệp hỏi mình mấy lần.\"</p>\n      <div class=\"ep-rev-author\"><div class=\"ep-rev-av\">NA</div><div><div class=\"ep-rev-name\">Ngọc Anh</div><div class=\"ep-rev-city\">TP. Hồ Chí Minh</div></div></div>\n    </div>\n    <div class=\"ep-rev r\">\n      <div class=\"ep-rev-stars\">★★★★★</div>\n      <p class=\"ep-rev-text\">\"Đặt làm quà sinh nhật cho bạn gái, bạn ấy thích lắm! Mùi tinh tế, không quá ngọt, đúng gu con gái hiện đại. Giao hàng nhanh, đóng gói đẹp.\"</p>\n      <div class=\"ep-rev-author\"><div class=\"ep-rev-av\">MT</div><div><div class=\"ep-rev-name\">Minh Tuấn</div><div class=\"ep-rev-city\">Hà Nội</div></div></div>\n    </div>\n    <div class=\"ep-rev r\">\n      <div class=\"ep-rev-stars\">★★★★★</div>\n      <p class=\"ep-rev-text\">\"Đi làm ai cũng hỏi mình xài nước hoa gì. Giá hợp lý mà chất lượng không thua thương hiệu lớn. Đã mua lần 3 rồi, sẽ còn mua tiếp!\"</p>\n      <div class=\"ep-rev-author\"><div class=\"ep-rev-av\">LB</div><div><div class=\"ep-rev-name\">Lan Bình</div><div class=\"ep-rev-city\">Đà Nẵng</div></div></div>\n    </div>\n  </div>\n</section>\n\n<!-- ORDER -->\n<section class=\"ep-order\" id=\"epOrder\">\n  <div class=\"ep-order-inner\">\n    <div class=\"r\">\n      <h2 class=\"ep-order-title\">Sở hữu <em>mùi hương</em><br>của riêng bạn</h2>\n      <p class=\"ep-order-desc\">Điền thông tin bên cạnh — chúng tôi sẽ liên hệ xác nhận trong vòng 15 phút và giao hàng tận nơi trên toàn quốc.</p>\n      <div class=\"ep-perks\">\n        <div class=\"ep-perk\"><div class=\"ep-perk-ico\">🚚</div>Miễn phí vận chuyển toàn quốc</div>\n        <div class=\"ep-perk\"><div class=\"ep-perk-ico\">🔄</div>Đổi trả miễn phí trong 7 ngày</div>\n        <div class=\"ep-perk\"><div class=\"ep-perk-ico\">🎁</div>Hộp quà cao cấp kèm thiệp miễn phí</div>\n        <div class=\"ep-perk\"><div class=\"ep-perk-ico\">💳</div>Thanh toán khi nhận hàng (COD)</div>\n      </div>\n    </div>\n\n    <div class=\"ep-form-box r\">\n      <h3 class=\"ep-form-title\">Đặt hàng ngay</h3>\n      <p class=\"ep-form-sub\">Điền thông tin · nhận hàng trong 1–3 ngày</p>\n      <div id=\"epFormBody\">\n        <div class=\"ep-fg\">\n          <label>Họ và tên *</label>\n          <input type=\"text\" id=\"epName\" placeholder=\"Nguyễn Thị Lan Anh\">\n        </div>\n        <div class=\"ep-form-row\">\n          <div class=\"ep-fg\">\n            <label>Số điện thoại *</label>\n            <input type=\"tel\" id=\"epPhone\" placeholder=\"0901 234 567\">\n          </div>\n          <div class=\"ep-fg\">\n            <label>Tỉnh / Thành phố *</label>\n            <div class=\"ep-sel-wrap\">\n              <select id=\"epCity\">\n                <option value=\"\">Chọn tỉnh thành</option>\n                <option>TP. Hồ Chí Minh</option>\n                <option>Hà Nội</option>\n                <option>Đà Nẵng</option>\n                <option>Cần Thơ</option>\n                <option>Hải Phòng</option>\n                <option>Bình Dương</option>\n                <option>Đồng Nai</option>\n                <option>Long An</option>\n                <option>Tây Ninh</option>\n                <option>Tỉnh thành khác</option>\n              </select>\n            </div>\n          </div>\n        </div>\n        <div class=\"ep-fg\">\n          <label>Địa chỉ nhận hàng *</label>\n          <input type=\"text\" id=\"epAddr\" placeholder=\"Số nhà, đường, phường/xã...\">\n        </div>\n        <div class=\"ep-fg\">\n          <label>Số lượng</label>\n          <div class=\"ep-qty\">\n            <button class=\"ep-qty-btn\" type=\"button\" onclick=\"epQty(-1)\">−</button>\n            <input class=\"ep-qty-val\" type=\"number\" id=\"epQty\" value=\"1\" min=\"1\" max=\"10\" readonly>\n            <button class=\"ep-qty-btn\" type=\"button\" onclick=\"epQty(1)\">+</button>\n          </div>\n        </div>\n        <div class=\"ep-fg\">\n          <label>Ghi chú (tuỳ chọn)</label>\n          <textarea id=\"epNote\" placeholder=\"Giao giờ hành chính, cần hộp quà...\"></textarea>\n        </div>\n        <div class=\"ep-total-row\">\n          <span class=\"ep-total-label\">Tổng tiền (chưa phí ship)</span>\n          <span class=\"ep-total\" id=\"epTotal\">599.000₫</span>\n        </div>\n        <button class=\"ep-submit\" type=\"button\" onclick=\"epSubmit()\">\n          <span>Xác nhận đặt hàng</span><span>→</span>\n        </button>\n        <p class=\"ep-form-note\">🔒 Thông tin của bạn được bảo mật tuyệt đối.<br>Chúng tôi sẽ gọi xác nhận trong vòng 15 phút.</p>\n      </div>\n      <div class=\"ep-success\" id=\"epSuccess\">\n        <div class=\"ep-success-ico\">🎉</div>\n        <div class=\"ep-success-title\">Đặt hàng thành công!</div>\n        <div class=\"ep-success-body\">Cảm ơn bạn đã tin tưởng ELORA.<br>Chúng tôi sẽ gọi xác nhận trong <strong>15 phút</strong>.<br>Hàng sẽ đến tay bạn trong 1–3 ngày làm việc.</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- FOOTER -->\n<footer class=\"ep-footer\">\n  <div class=\"ep-footer-logo\">ELORA</div>\n  <div class=\"ep-footer-eye\">Essence of Elegance</div>\n  <div class=\"ep-footer-links\">\n    <a href=\"#\">Về chúng tôi</a>\n    <a href=\"#\">Chính sách đổi trả</a>\n    <a href=\"#\">Bảo mật thông tin</a>\n    <a href=\"#\">Liên hệ</a>\n  </div>\n  <p class=\"ep-footer-copy\">© 2026 ELORA Perfume. All rights reserved.</p>\n</footer>\n\n<script>\n(function(){\n  // Slider\n  var idx=0;\n  var slides=document.querySelectorAll('#elora-page .ep-slide');\n  var dots=document.querySelectorAll('#elora-page .ep-dot');\n  var timer=setInterval(function(){epSlide(1);},4200);\n  window.epGoTo=function(n){\n    slides[idx].classList.remove('on');\n    dots[idx].classList.remove('on');\n    idx=n;\n    slides[idx].classList.add('on');\n    dots[idx].classList.add('on');\n    clearInterval(timer);\n    timer=setInterval(function(){epSlide(1);},4200);\n  };\n  window.epSlide=function(d){\n    epGoTo((idx+d+slides.length)%slides.length);\n  };\n\n  // Scroll reveal\n  var rs=document.querySelectorAll('#elora-page .r');\n  var ro=new IntersectionObserver(function(entries){\n    entries.forEach(function(e,i){\n      if(e.isIntersecting){\n        setTimeout(function(){e.target.classList.add('on');},i*80);\n        ro.unobserve(e.target);\n      }\n    });\n  },{threshold:0.1});\n  rs.forEach(function(el){ro.observe(el);});\n\n  // Qty\n  var UNIT=599000;\n  window.epQty=function(d){\n    var el=document.getElementById('epQty');\n    var v=Math.max(1,Math.min(10,parseInt(el.value)+d));\n    el.value=v;\n    document.getElementById('epTotal').textContent=(v*UNIT).toLocaleString('vi-VN')+'₫';\n  };\n\n  // Submit\n  window.epSubmit=function(){\n    var name=document.getElementById('epName').value.trim();\n    var phone=document.getElementById('epPhone').value.trim();\n    var city=document.getElementById('epCity').value;\n    var addr=document.getElementById('epAddr').value.trim();\n    if(!name){alert('Vui lòng nhập họ và tên.');return;}\n    if(!phone){alert('Vui lòng nhập số điện thoại.');return;}\n    if(!city){alert('Vui lòng chọn tỉnh thành.');return;}\n    if(!addr){alert('Vui lòng nhập địa chỉ nhận hàng.');return;}\n    document.getElementById('epFormBody').style.display='none';\n    var s=document.getElementById('epSuccess');\n    s.classList.add('show');\n    s.scrollIntoView({behavior:'smooth',block:'center'});\n  };\n})();\n</script>\n\n</div><!-- #elora-page -->\n\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t</div>\n\t\t\t\t\t</div>\n\t\t</section>\n\t\t\t\t<section class=\"elementor-section elementor-top-section elementor-element elementor-element-13538f7 elementor-section-boxed elementor-section-height-default elementor-section-height-default\" data-id=\"13538f7\" data-element_type=\"section\" data-e-type=\"section\">\n\t\t\t\t\t\t<div class=\"elementor-container elementor-column-gap-default\">\n\t\t\t\t\t<div class=\"elementor-column elementor-col-100 elementor-top-column elementor-element elementor-element-294edc3\" data-id=\"294edc3\" data-element_type=\"column\" data-e-type=\"column\">\n\t\t\t<div class=\"elementor-widget-wrap elementor-element-populated\">\n\t\t\t\t\t\t<div class=\"elementor-element elementor-element-923b435 elementor-widget elementor-widget-video\" data-id=\"923b435\" data-element_type=\"widget\" data-e-type=\"widget\" data-settings=\"{&quot;youtube_url&quot;:&quot;https:\\/\\/youtube.com\\/shorts\\/pKcdBZJRmks?si=0WY19u3RWrZMGd_8&quot;,&quot;autoplay&quot;:&quot;yes&quot;,&quot;video_type&quot;:&quot;youtube&quot;,&quot;controls&quot;:&quot;yes&quot;}\" data-widget_type=\"video.default\">\n\t\t\t\t<div class=\"elementor-widget-container\">\n\t\t\t\t\t\t\t<div class=\"elementor-wrapper elementor-open-inline\">\n\t\t\t<div class=\"elementor-video\"></div>\t\t</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t</div>\n\t\t\t\t\t</div>\n\t\t</section>\n\t\t\t\t<section class=\"elementor-section elementor-top-section elementor-element elementor-element-bb51a45 elementor-section-boxed elementor-section-height-default elementor-section-height-default\" data-id=\"bb51a45\" data-element_type=\"section\" data-e-type=\"section\">\n\t\t\t\t\t\t<div class=\"elementor-container elementor-column-gap-default\">\n\t\t\t\t\t<div class=\"elementor-column elementor-col-100 elementor-top-column elementor-element elementor-element-70fbe3f\" data-id=\"70fbe3f\" data-element_type=\"column\" data-e-type=\"column\">\n\t\t\t<div class=\"elementor-widget-wrap elementor-element-populated\">\n\t\t\t\t\t\t<div class=\"elementor-element elementor-element-35d8cc2 elementor-widget elementor-widget-html\" data-id=\"35d8cc2\" data-element_type=\"widget\" data-e-type=\"widget\" data-widget_type=\"html.default\">\n\t\t\t\t<div class=\"elementor-widget-container\">\n\t\t\t\t\t<script src=\"https://js-na2.hsforms.net/forms/embed/246742911.js\" defer></script>\n<div class=\"hs-form-frame\" data-region=\"na2\" data-form-id=\"26bee9ff-23d4-4278-bc84-646c9445b009\" data-portal-id=\"246742911\"></div>\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t</div>\n\t\t\t\t\t</div>\n\t\t</section>\n\t\t\t\t</div>"
